<script setup lang="ts">
import{ref}from'vue';import{locale}from'../i18n';import WorkspaceIcon from'./WorkspaceIcon.vue';
const busy=ref(false),error=ref('');const tr=(a:string,b:string)=>locale.value==='id'?a:b;
async function leave(){if(busy.value)return;if(document.querySelector('[data-leave-confirmation="true"]')&&!confirm(tr('Ada transaksi yang belum selesai. Tetap keluar?','There is an unfinished sale. Sign out?')))return;busy.value=true;error.value='';try{const r=await fetch('/auth/logout',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??''},signal:AbortSignal.timeout(15000)});if(!r.ok&&r.status!==401)throw Error();location.replace('/business-login');}catch{error.value=tr('Belum berhasil keluar. Coba lagi.','Sign out failed. Try again.');}finally{busy.value=false;}}
</script>
<template><details class="account-menu"><summary><WorkspaceIcon name="users"/>{{tr('Akun','Account')}}</summary><div><a href="/pos/business/security"><WorkspaceIcon name="shield-check"/>{{tr('Keamanan & TOTP','Security & TOTP')}}</a><button @click="leave" :disabled="busy"><WorkspaceIcon name="log-out"/>{{tr('Ganti akun','Switch account')}}</button><button @click="leave" :disabled="busy"><WorkspaceIcon name="log-out"/>{{busy?tr('Keluar…','Signing out…'):tr('Keluar','Sign out')}}</button><p v-if="error" role="alert">{{error}}</p></div></details></template>
<style scoped>.account-menu{position:relative;font-size:16px}.account-menu summary{display:flex;align-items:center;gap:8px;cursor:pointer;list-style:none}.account-menu>div{position:absolute;right:0;top:36px;min-width:240px;padding:12px;border:1px solid #E9EBFF;border-radius:16px;background:#FFFFFF;box-shadow:0 12px 32px #1B1B391A;z-index:80;color:#1B1B39}.account-menu a,.account-menu button{display:flex;gap:10px;align-items:center;padding:12px;width:100%;text-decoration:none;border:0;background:#FFFFFF;font:500 16px system-ui;color:#1B1B39;text-align:left}.account-menu a:hover,.account-menu button:hover{background:#E9EBFF}</style>
